import type { DbDriver } from '../types/db.js';
import { NOOP_LOGGER, type RepoLogger } from '../types/logger.js';
import { nowTimestamp } from '../utils/timestamp.js';

export interface SettingsRepositoryOptions {
    log?: RepoLogger;
}

/**
 * Story 390 — the synced `settings` key/value table, for the server and the PWA alike. A missing
 * key reads as `null`; parsing a value is the caller's.
 */
export function createSettingsRepository(driver: DbDriver, options: SettingsRepositoryOptions = {}) {
    const log = options.log ?? NOOP_LOGGER;
    const repository = {
        async get(key: string): Promise<string | null> {
            log.debug('settings.get', { key });
            const row = await driver.queryOne<{ value: string }>('SELECT value FROM settings WHERE key = ?', [key]);
            return row?.value ?? null;
        },

        async getMany(keys: readonly string[]): Promise<Record<string, string | null>> {
            const result: Record<string, string | null> = {};
            for (const key of keys) {
                result[key] = await repository.get(key);
            }
            return result;
        },

        async set(key: string, value: string): Promise<void> {
            log.debug('settings.set', { key });
            await driver.execute(
                `INSERT INTO settings (key, value, updated_at) VALUES (?, ?, ?)
                 ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at`,
                key,
                value,
                nowTimestamp(),
            );
        },

        async delete(key: string): Promise<void> {
            log.debug('settings.delete', { key });
            await driver.execute('DELETE FROM settings WHERE key = ?', key);
        },

        /** Deletes the keys under `prefix` that sort before `key`, itself a key under `prefix`. */
        async deleteBefore(prefix: string, key: string): Promise<void> {
            if (!key.startsWith(prefix)) throw new Error(`settings.deleteBefore: '${key}' is not under '${prefix}'`);
            log.debug('settings.deleteBefore', { prefix, key });
            await driver.execute('DELETE FROM settings WHERE key >= ? AND key < ?', prefix, key);
        },
    };
    return repository;
}

export type SettingsRepository = ReturnType<typeof createSettingsRepository>;
